package com.atlashub.pay.txquery.application.queries.GetTransactionVolume;import com.atlashub.pay.txquery.application.queries.TransactionResults.VolumeResult;import com.atlashub.pay.txquery.domain.repositories.TransactionRecordRepository;import com.atlashub.shared.application.usecase.Query;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Component;@Component public class GetTransactionVolumeHandler extends Query<GetTransactionVolumeQuery,VolumeResult>{private final TransactionRecordRepository repository;public GetTransactionVolumeHandler(TransactionRecordRepository r){repository=r;}@Override @PreAuthorize("hasAuthority('pay:ledger:read')")public VolumeResult execute(GetTransactionVolumeQuery q){var v=repository.calculateVolume(q.organizationId(),q.environment(),q.month());return new VolumeResult(q.organizationId(),q.month().toString(),v.chargeCount(),v.chargeAmount(),v.payoutCount(),v.payoutAmount(),v.currency());}}
